"use client";

import { useFinanceData } from "@/components/finance/useFinanceData";
import { motion } from "framer-motion";
import { useEffect, useState } from "react";
import { useReducedMotion } from "@/components/finance/useFinanceData";

const AllocationDonut = ({ data }: { data: number[] }) => {
  const [path, setPath] = useState<string | null>(null);
  const isReducedMotion = useReducedMotion();

  useEffect(() => {
    if (data.length === 0) return;
    const min = Math.min(...data);
    const max = Math.max(...data);
    const pathData = data.map((value, index) => {
      const angle = ((value - min) / (max - min)) * 360;
      return `M 50 50 L 50 50 A 50 50 0 ${angle > 180 ? 1 : 0} 1 ${50 + 50 * Math.cos((angle * Math.PI) / 180)} ${50 + 50 * Math.sin((angle * Math.PI) / 180)}`;
    }).join(" ");
    setPath(pathData);
  }, [data]);

  return (
    <motion.div
      className="relative w-40 h-40"
      initial={{ rotate: 0 }}
      animate={{ rotate: isReducedMotion ? 0 : 360 }}
      transition={{ duration: 2, repeat: Infinity }}
    >
      <svg className="w-full h-full" viewBox="0 0 100 100">
        <path d="M 50 50 L 50 50 A 50 50 0 0 1 50 50" fill="white" />
        {path && <path d={path} fill="blue" />}
      </svg>
    </motion.div>
  );
};

